<style>
:root{--wolf-dark:#142322;--wolf-ink:#20242b;--wolf-muted:#656b73;--wolf-gold:#c9a57d;--wolf-gold-dark:#bd9669;--wolf-soft:#f4f6f5;--wolf-line:#e7e9e7;--wolf-white:#fff}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:#fff;color:var(--wolf-ink);font-family:Arial,"Helvetica Neue",sans-serif;font-size:16px;line-height:1.55}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}
button,input,textarea{font:inherit}
.xd324-container{width:min(1660px,calc(100% - 64px));margin:0 auto}
.xd324-header{position:fixed;top:0;left:0;right:0;z-index:60;color:#fff;border-bottom:1px solid rgba(255,255,255,.12);transition:background .25s ease,box-shadow .25s ease}
.xd324-header.is-scrolled{background:rgba(20,35,34,.94);box-shadow:0 14px 30px rgba(0,0,0,.18);backdrop-filter:blur(12px)}
.xd324-header__inner{height:72px;display:grid;grid-template-columns:220px 1fr auto;align-items:center;gap:24px}
.xd324-brand{font-size:37px;font-weight:900;letter-spacing:-1px}.xd324-brand img{max-height:46px}
.xd324-nav{display:flex;align-items:center;justify-content:center;gap:31px;font-weight:800}.xd324-nav a{opacity:.92}.xd324-nav a:hover{color:var(--wolf-gold)}
.xd324-actions{display:flex;align-items:center;gap:22px;font-size:22px}.xd324-actions>a,.xd324-actions>button{border:0;background:transparent;color:#fff;padding:0;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}.xd324-admin{font-size:13px;border:1px solid rgba(255,255,255,.35)!important;border-radius:999px;padding:4px 10px!important}
.xd324-badge{position:relative}.xd324-badge span{position:absolute;top:-15px;right:-12px;min-width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:900;background:#1aa36f}.xd324-badge--cart span{background:#f3bc12;color:#101010}
.xd324-menu-toggle{display:none;border:0;background:rgba(255,255,255,.16);color:#fff;width:42px;height:42px;border-radius:50%}
.xd324-hero{position:relative;min-height:100vh;background:var(--wolf-dark);overflow:hidden;color:#fff}
.xd324-hero__slide{position:absolute;inset:0;opacity:0;transition:opacity .75s ease;pointer-events:none}.xd324-hero__slide.is-active{opacity:1;pointer-events:auto}
.xd324-hero__slide>img{width:100%;height:100%;object-fit:cover;transform:scale(1.04);transition:transform 7s ease}.xd324-hero__slide.is-active>img{transform:scale(1)}
.xd324-hero__shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.78),rgba(20,35,34,.45),rgba(0,0,0,.52))}
.xd324-hero__content{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding-top:70px;max-width:none}.xd324-hero__content p{font-size:18px;font-weight:800;margin:0 0 18px}.xd324-hero h1{font-size:60px;line-height:1.08;margin:0 0 28px;color:#fff;letter-spacing:-1px}.xd324-hero__content span{font-size:25px;max-width:620px;color:rgba(255,255,255,.92)}
.xd324-hero__nav{position:absolute;top:28px;z-index:5;width:42px;height:42px;border:0;border-radius:50%;background:rgba(255,255,255,.08);color:#fff;cursor:pointer}.xd324-hero__nav--prev{right:570px}.xd324-hero__nav--next{right:520px}
.xd324-float{position:fixed;z-index:55;width:48px;height:48px;border-radius:50%;background:var(--wolf-gold);color:#fff;display:grid;place-items:center;box-shadow:0 12px 28px rgba(0,0,0,.2)}.xd324-float--bell{left:18px;bottom:28px}.xd324-float--phone{right:24px;bottom:28px;width:64px;height:64px;background:#fff;color:var(--wolf-gold);border:8px solid var(--wolf-gold)}
.xd324-section{padding:92px 0}.xd324-eyebrow{text-transform:uppercase;color:var(--wolf-gold);font-size:25px;font-weight:900;margin:0 0 12px}.xd324-section h2,.xd324-split-heading h2,.xd324-process h2{font-size:58px;line-height:1.12;letter-spacing:-1px;margin:0;color:var(--wolf-ink)}.xd324-section h2 em,.xd324-split-heading h2 em,.xd324-process h2 em{font-style:normal;color:var(--wolf-gold)}
.xd324-btn{display:inline-flex;align-items:center;gap:18px;justify-content:center;min-height:58px;padding:0 28px;border-radius:7px;background:var(--wolf-gold);color:#fff;font-size:22px;font-weight:800}.xd324-btn:hover{background:var(--wolf-gold-dark)}
.xd324-about__grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}.xd324-about__mosaic{display:grid;grid-template-columns:1fr 1fr;gap:18px}.xd324-about__mosaic img{width:100%;height:370px;object-fit:cover;border-radius:12px;box-shadow:0 15px 35px rgba(30,30,30,.12)}.xd324-about__mosaic img:nth-child(2){margin-top:36px}.xd324-about__mosaic img:nth-child(3){margin-top:-18px}.xd324-about__body>p:not(.xd324-eyebrow){font-size:22px;color:#30343b;margin:24px 0}.xd324-about__stats{display:grid;grid-template-columns:repeat(3,1fr);gap:35px;margin:30px 0}.xd324-about__stats strong{display:block;color:var(--wolf-gold);font-size:47px;line-height:1;font-weight:900}.xd324-about__stats span{font-size:20px;color:#2d333b}
.xd324-values,.xd324-signature{background:#f7f7f7}.xd324-values__grid{display:grid;grid-template-columns:1fr 1fr;gap:66px;align-items:center}.xd324-lead{font-size:24px;color:#30343b;margin:28px 0 36px}.xd324-value-list{display:grid}.xd324-value-list article{display:grid;grid-template-columns:92px 1fr;gap:22px;padding:30px 0;border-bottom:1px solid var(--wolf-line)}.xd324-value-list i{width:82px;height:82px;border-radius:50%;background:#edf3ef;display:grid;place-items:center;color:#1c2727;font-size:32px}.xd324-value-list h3{font-size:28px;margin:0 0 8px}.xd324-value-list p{font-size:22px;color:#30343b;margin:0}.xd324-values__mosaic{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:center}.xd324-values__mosaic img{width:100%;height:258px;object-fit:cover;border-radius:16px}.xd324-values__mosaic img:first-child{height:430px}.xd324-values__mosaic img:nth-child(4){height:430px}.xd324-values__mosaic--alt img:first-child{height:430px}.xd324-values__mosaic--alt img:nth-child(4){height:430px}
.xd324-split-heading{display:grid;grid-template-columns:1.15fr .85fr;gap:80px;align-items:start;margin-bottom:62px}.xd324-split-heading>p{font-size:25px;color:#252a31;margin:54px 0 0}.xd324-center{text-align:center;margin-top:36px}.xd324-card-track,.xd324-news-track{display:grid;grid-auto-flow:column;gap:22px;overflow-x:auto;overscroll-behavior-inline:contain;scroll-snap-type:x mandatory;scrollbar-width:none;cursor:grab}.xd324-card-track::-webkit-scrollbar,.xd324-news-track::-webkit-scrollbar{display:none}.xd324-card-track.is-dragging,.xd324-news-track.is-dragging{cursor:grabbing;scroll-snap-type:none}
.xd324-service-card{position:relative;scroll-snap-align:start;width:420px;height:620px;border-radius:16px;overflow:hidden;color:#fff;isolation:isolate}.xd324-service-card img,.xd324-project-card img{width:100%;height:100%;object-fit:cover;transition:transform .45s ease}.xd324-service-card::after,.xd324-project-card::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.78));z-index:1}.xd324-service-card div{position:absolute;left:28px;right:28px;bottom:28px;z-index:2}.xd324-service-card h3{font-size:29px;line-height:1.2;margin:0 0 12px}.xd324-service-card p{font-size:22px;margin:0 0 14px}.xd324-service-card a{font-size:22px;font-weight:800;text-decoration:underline}.xd324-service-card:hover img,.xd324-project-card:hover img{transform:scale(1.07)}
.xd324-projects{background:#f8f8f8}.xd324-card-track--wide{gap:20px}.xd324-project-card{position:relative;scroll-snap-align:start;width:600px;height:460px;overflow:hidden;color:#fff;isolation:isolate}.xd324-project-card a{position:absolute;right:30px;top:30px;z-index:3;width:78px;height:78px;border-radius:50%;background:var(--wolf-gold);display:grid;place-items:center;font-size:32px}.xd324-project-card h3{position:absolute;left:38px;right:38px;bottom:56px;z-index:2;text-align:center;font-size:29px;line-height:1.2;margin:0}
.xd324-process{background:var(--wolf-dark);color:#fff;padding:88px 0}.xd324-process .xd324-eyebrow{color:var(--wolf-gold)}.xd324-process h2{color:#fff}.xd324-process__head{display:grid;grid-template-columns:1fr 1fr;gap:90px;margin-bottom:92px}.xd324-process__head>p{font-size:22px;margin:34px 0 0;color:#f1f4f2}.xd324-process__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:54px}.xd324-process article i{font-size:66px;color:#fff;margin-bottom:36px}.xd324-process h3{font-size:24px;line-height:1.2;margin:0 0 18px;color:#fff}.xd324-process article p{font-size:20px;color:#e7eeee;margin:0}
.xd324-news-track{gap:24px}.xd324-news article{scroll-snap-align:start;width:500px}.xd324-news img{width:100%;height:320px;object-fit:cover}.xd324-news h3{font-size:25px;line-height:1.22;margin:16px 0 20px}.xd324-news p{font-size:21px;color:#555b64;margin:0 0 14px}.xd324-news time{font-size:18px;color:#8b8f95}.xd324-empty{grid-column:1/-1;color:var(--wolf-muted)}
.xd324-footer{background:var(--wolf-dark);color:#fff;padding:62px 0 0}.xd324-footer__top{display:flex;align-items:center;justify-content:space-between;padding-bottom:56px;border-bottom:1px solid rgba(255,255,255,.12)}.xd324-footer__logo{font-size:44px;font-weight:900}.xd324-footer__social{display:flex;align-items:center;gap:16px;font-size:24px;font-weight:900}.xd324-footer__social a{width:52px;height:52px;border-radius:50%;background:#fff;color:var(--wolf-dark);display:grid;place-items:center}.xd324-footer__grid{display:grid;grid-template-columns:1.2fr 1fr 1.2fr 1fr;gap:70px;padding:58px 0}.xd324-footer h3{font-size:24px;margin:0 0 20px}.xd324-footer p,.xd324-footer a{font-size:20px;color:#fff;margin:0 0 14px}.xd324-footer section a{display:block}.xd324-footer p{display:grid;grid-template-columns:26px 1fr;gap:10px}.xd324-footer__bottom{text-align:center;border-top:1px solid rgba(255,255,255,.12);padding:28px 0;font-size:18px}
.reveal{opacity:0;transform:translateY(34px);transition:opacity .7s ease,transform .7s ease}.reveal.is-visible{opacity:1;transform:none}.xd324-service-card,.xd324-project-card,.xd324-news article{transition:transform .25s ease,box-shadow .25s ease}.xd324-service-card:hover,.xd324-project-card:hover,.xd324-news article:hover{transform:translateY(-8px)}
@media(max-width:1200px){.xd324-header__inner{grid-template-columns:170px auto auto}.xd324-nav{gap:16px;font-size:14px}.xd324-actions{gap:14px}.xd324-about__grid,.xd324-values__grid,.xd324-split-heading,.xd324-process__head{grid-template-columns:1fr}.xd324-process__grid{grid-template-columns:repeat(2,1fr)}.xd324-footer__grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:820px){.xd324-container{width:min(100% - 28px,720px)}.xd324-header__inner{height:66px;grid-template-columns:1fr auto}.xd324-brand{font-size:30px}.xd324-menu-toggle{display:grid;place-items:center}.xd324-nav{position:absolute;top:100%;left:0;right:0;background:rgba(20,35,34,.98);display:none;flex-direction:column;align-items:flex-start;padding:18px 22px}.xd324-nav.is-open{display:flex}.xd324-actions{grid-column:1/-1;justify-content:flex-end;font-size:18px;display:none}.xd324-header.is-open .xd324-actions{display:flex}.xd324-hero h1{font-size:44px}.xd324-hero__content span{font-size:20px}.xd324-hero__nav{display:none}.xd324-section{padding:64px 0}.xd324-section h2,.xd324-split-heading h2,.xd324-process h2{font-size:38px}.xd324-about__mosaic img{height:230px}.xd324-about__stats{grid-template-columns:1fr}.xd324-value-list article{grid-template-columns:70px 1fr}.xd324-value-list i{width:62px;height:62px}.xd324-value-list h3{font-size:23px}.xd324-value-list p,.xd324-lead,.xd324-split-heading>p{font-size:18px}.xd324-values__mosaic img,.xd324-values__mosaic img:first-child,.xd324-values__mosaic img:nth-child(4){height:220px}.xd324-service-card{width:82vw;height:520px}.xd324-project-card{width:86vw;height:360px}.xd324-news article{width:82vw}.xd324-news img{height:250px}.xd324-process__grid{grid-template-columns:1fr}.xd324-footer__top{align-items:flex-start;gap:24px;flex-direction:column}.xd324-footer__grid{grid-template-columns:1fr}.xd324-float--bell{display:none}}
</style>
